/// Parsed test parameters with raw byte arrays ready for use.
struct TestParams {
    order_hash: [u8; 32],
    ad_root: [u8; 32],
    order_root: [u8; 32],
    bridger_nullifier: [u8; 32],
    ad_creator_nullifier: [u8; 32],
    // Contract addresses
    ad_manager_id: [u8; 32],
    order_portal_id: [u8; 32],
    // Order fields
    order_chain_token: [u8; 32],
    ad_chain_token: [u8; 32],
    amount: u128,
    bridger: [u8; 32],
    order_recipient: [u8; 32],
    ad_creator: [u8; 32],
    ad_recipient: [u8; 32],
    salt: u128,
    ad_id: std::string::String,
    order_decimals: u32,
    ad_decimals: u32,
    deadline: u64,
    ad_settlement_signer: [u8; 32],
    // Chain IDs
    order_chain_id: u128,
    ad_chain_id: u128,
    // Event-claim roots for domains 2, 3, 4
    event_roots: [[u8; 32]; 4],
    // 2.5c: a CANCEL root for a DIFFERENT order (the reuse negative)
    foreign_cancel_root: [u8; 32],
}

fn hex_to_array(hex_str: &str) -> [u8; 32] {
    let clean = hex_str.strip_prefix("0x").unwrap_or(hex_str);
    let mut arr = [0u8; 32];
    hex::decode_to_slice(clean, &mut arr).unwrap();
    arr
}

/// Decode a Stellar strkey address (C... or G...) to its 32-byte payload
fn strkey_to_array(strkey: &str) -> [u8; 32] {
    if strkey.starts_with('C') {
        stellar_strkey::Contract::from_string(strkey)
            .expect("invalid C... address")
            .0
    } else if strkey.starts_with('G') {
        stellar_strkey::ed25519::PublicKey::from_string(strkey)
            .expect("invalid G... address")
            .0
    } else {
        panic!("Unknown strkey prefix: {}", strkey);
    }
}

fn load_test_params() -> TestParams {
    let json: TestParamsJson = serde_json::from_str(TEST_PARAMS_JSON).unwrap();
    TestParams {
        // These remain 0x hex (proof-derived values)
        order_hash: hex_to_array(&json.order_hash),
        ad_root: hex_to_array(&json.ad_root),
        order_root: hex_to_array(&json.order_root),
        bridger_nullifier: hex_to_array(&json.bridger_nullifier),
        ad_creator_nullifier: hex_to_array(&json.ad_creator_nullifier),
        // Contract addresses (C... strkey format)
        ad_manager_id: strkey_to_array(&json.contract_addresses.ad_manager),
        order_portal_id: strkey_to_array(&json.contract_addresses.order_portal),
        // Token addresses (C... strkey format)
        order_chain_token: strkey_to_array(&json.order_params.order_chain_token),
        ad_chain_token: strkey_to_array(&json.order_params.ad_chain_token),
        amount: json.order_params.amount.parse().unwrap(),
        // User addresses (G... strkey format)
        bridger: strkey_to_array(&json.order_params.bridger),
        order_recipient: strkey_to_array(&json.order_params.order_recipient),
        ad_creator: strkey_to_array(&json.order_params.ad_creator),
        ad_recipient: strkey_to_array(&json.order_params.ad_recipient),
        salt: json.order_params.salt.parse().unwrap(),
        ad_id: json.order_params.ad_id,
        order_decimals: json.order_params.order_decimals,
        ad_decimals: json.order_params.ad_decimals,
        deadline: json.order_params.deadline.parse().unwrap(),
        ad_settlement_signer: strkey_to_array(&json.order_params.ad_settlement_signer),
        order_chain_id: json.chain_ids.order_chain_id,
        ad_chain_id: json.chain_ids.ad_chain_id,
        event_roots: [2u32, 3, 4, 5].map(|d| hex_to_array(&json.event_roots[&d.to_string()])),
        foreign_cancel_root: hex_to_array(&json.event_roots["2foreign"]),
    }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

fn bytes32_to_bytesn(env: &Env, arr: &[u8; 32]) -> BytesN<32> {
    BytesN::from_array(env, arr)
}

/// Create an Address from a 32-byte contract ID
fn contract_address(env: &Env, id: &[u8; 32]) -> Address {
    let strkey = Contract(*id).to_string();
    let soroban_str = SorobanString::from_str(env, &strkey);
    Address::from_string(&soroban_str)
}

// ---------------------------------------------------------------------------
// Test setup
// ---------------------------------------------------------------------------

#[allow(dead_code)]
struct TestSetup<'a> {
    env: Env,
    // Fixture params (loaded from test_params.json)
    tp: TestParams,
    // Contracts
    ad_manager: ad_manager_contract::Client<'a>,
    order_portal: order_portal_contract::Client<'a>,
    // T-25 leaf attribution: each leg's own merkle manager
    ad_merkle_addr: Address,
    order_merkle_addr: Address,
    // Admin
    admin_addr: Address,
    // The ad's maker: the account the fixture's `ad_creator` encodes (2.3c binds them at lock).
    maker_addr: Address,
    // The key registry the ad-manager consults for settlement signers (a mock; one test uses the real one).
    key_registry: Address,
    // Token addresses (deployed test-token contracts)
    ad_token_addr: Address,
    order_token_addr: Address,
}

/// Standard setup: wires a MockRootVerifier that accepts every root on both
/// escrows (the gate is mandatory now — unlock fails without a module).
fn setup() -> TestSetup<'static> {
    setup_with_verifiers(true)
}

fn setup_with_verifiers(wire_root_verifiers: bool) -> TestSetup<'static> {
    setup_opts(wire_root_verifiers, true)
}

/// 2.3e: the suite's clocks — no window bound, a 30-minute buffer, no margin, a 1-day backstop, no
/// stagger — the smallest legal set, so every existing lock/create/unlock keeps its shape.
const SUITE_BUFFER: u64 = 1_800;
const SUITE_LONG_BACKSTOP: u64 = 86_400;

fn ad_timing(
    min_window: u64,
    buffer: u64,
    margin: u64,
    long_backstop: u64,
    claim_stagger: u64,
) -> ad_manager_contract::RouteTiming {
    ad_manager_contract::RouteTiming {
        min_window,
        buffer,
        margin,
        long_backstop,
        claim_stagger,
    }
}

fn portal_timing(
    min_window: u64,
    buffer: u64,
    margin: u64,
    long_backstop: u64,
    claim_stagger: u64,
) -> order_portal_contract::RouteTiming {
    order_portal_contract::RouteTiming {
        min_window,
        buffer,
        margin,
        long_backstop,
        claim_stagger,
    }
}

fn setup_opts(wire_root_verifiers: bool, wire_timing: bool) -> TestSetup<'static> {
    let tp = load_test_params();

    let env = Env::default();
    env.mock_all_auths_allowing_non_root_auth();
    env.cost_estimate().budget().reset_unlimited();

    // Generate admin address
    let admin_addr = Address::generate(&env);

    // Deploy verifiers
    let vk_bytes = Bytes::from_slice(&env, VK);
    let ad_verifier_id = env.register(VERIFIER_WASM, (vk_bytes.clone(),));
    let order_verifier_id = env.register(VERIFIER_WASM, (vk_bytes,));

    // Deploy merkle managers
    let ad_merkle_id = env.register(MERKLE_WASM, ());
    let ad_merkle = merkle_contract::Client::new(&env, &ad_merkle_id);
    ad_merkle.initialize(&admin_addr);

    let order_merkle_id = env.register(MERKLE_WASM, ());
    let order_merkle = merkle_contract::Client::new(&env, &order_merkle_id);
    order_merkle.initialize(&admin_addr);

    // Deploy ad-manager at deterministic address
    let ad_manager_addr = contract_address(&env, &tp.ad_manager_id);
    env.register_at(&ad_manager_addr, AD_MANAGER_WASM, ());
    let ad_manager = ad_manager_contract::Client::new(&env, &ad_manager_addr);

    // Deploy order-portal at deterministic address
    let order_portal_addr = contract_address(&env, &tp.order_portal_id);
    env.register_at(&order_portal_addr, ORDER_PORTAL_WASM, ());
    let order_portal = order_portal_contract::Client::new(&env, &order_portal_addr);

    // Deploy SAC-convention tokens at deterministic addresses matching fixture params.
    // Both contracts resolve BytesN<32> → Contract address → token::Client
    let token_name = SorobanString::from_str(&env, "TestToken");
    let token_symbol = SorobanString::from_str(&env, "TT");
    let ad_token_addr = contract_address(&env, &tp.ad_chain_token);
    env.register_at(
        &ad_token_addr,
        TokenContract,
        (
            admin_addr.clone(),
            0i128,
            tp.ad_decimals,
            token_name.clone(),
            token_symbol.clone(),
        ),
    );

    let order_token_addr = contract_address(&env, &tp.order_chain_token);
    env.register_at(
        &order_token_addr,
        TokenContract,
        (
            admin_addr.clone(),
            0i128,
            tp.order_decimals,
            token_name.clone(),
            token_symbol.clone(),
        ),
    );

    // w_native_token is required by the constructor but not used for non-native tokens
    let w_native_token = ad_token_addr.clone();

    // Initialize contracts (uses require_auth, mocked)
    ad_manager.initialize(
        &admin_addr,
        &ad_verifier_id,
        &ad_merkle_id,
        &w_native_token,
        &tp.ad_chain_id,
    );
    order_portal.initialize(
        &admin_addr,
        &order_verifier_id,
        &order_merkle_id,
        &order_token_addr,
        &tp.order_chain_id,
    );

    // Set merkle managers
    ad_merkle.set_manager(&ad_manager_addr, &true);
    order_merkle.set_manager(&order_portal_addr, &true);

    // --- Ad-manager: set_chain (uses require_auth, mocked) ---
    ad_manager.set_chain(
        &tp.order_chain_id,
        &bytes32_to_bytesn(&env, &tp.order_portal_id),
        &true,
    );

    // --- Order-portal: set_chain (uses require_auth, mocked) ---
    order_portal.set_chain(
        &tp.ad_chain_id,
        &bytes32_to_bytesn(&env, &tp.ad_manager_id),
        &true,
    );

    // --- Ad-manager: set_token_route (uses require_auth, mocked) ---
    ad_manager.set_token_route(
        &bytes32_to_bytesn(&env, &tp.ad_chain_token),
        &bytes32_to_bytesn(&env, &tp.order_chain_token),
        &tp.order_chain_id,
    );

    // --- Order-portal: set_token_route (uses require_auth, mocked) ---
    order_portal.set_token_route(
        &bytes32_to_bytesn(&env, &tp.order_chain_token),
        &tp.ad_chain_id,
        &bytes32_to_bytesn(&env, &tp.ad_chain_token),
    );

    // 2.3e: timing is fail-closed on both legs.
    if wire_timing {
        ad_manager.set_route_timing(
            &tp.order_chain_id,
            &ad_timing(0, SUITE_BUFFER, 0, SUITE_LONG_BACKSTOP, 0),
        );
        order_portal.set_route_timing(
            &tp.ad_chain_id,
            &portal_timing(0, SUITE_BUFFER, 0, SUITE_LONG_BACKSTOP, 0),
        );
    }

    // The maker is the account the fixture's `ad_creator` encodes: 2.3c checks
    // `params.ad_creator == address_to_bytes32(ad.maker)` at lock, so the ad must be
    // created by that address rather than the random admin.
    let maker_addr = Address::from_string(&SorobanString::from_str(
        &env,
        &stellar_strkey::ed25519::PublicKey(tp.ad_creator).to_string(),
    ));

    // Mint tokens to admin and maker via the SAC-convention token
    let ad_token_client = TokenContractClient::new(&env, &ad_token_addr);
    ad_token_client.mint(&admin_addr, &(tp.amount as i128 * 10));
    ad_token_client.mint(&maker_addr, &(tp.amount as i128 * 10));

    // Root-verification gate is mandatory: wire a permissive mock by default.
    if wire_root_verifiers {
        let mock = env.register(MockRootVerifier, ());
        MockRootVerifierClient::new(&env, &mock).set_ok(&true);
        ad_manager.set_root_verifier(&tp.order_chain_id, &mock);
        order_portal.set_root_verifier(&tp.ad_chain_id, &mock);
    }

    // 2.3c: the settlement signer must hold a usable key. A mock registry marks the fixture's
    // (split-case) signer registered; `test_t14_real_registry_gates_the_signer` uses the real one.
    let key_registry = env.register(MockKeyRegistry, ());
    MockKeyRegistryClient::new(&env, &key_registry)
        .set(&bytes32_to_bytesn(&env, &tp.ad_settlement_signer), &true);
    ad_manager.set_key_registry(&key_registry);

    // --- Ad-manager: create_ad (creator wallet auth, mocked) ---
    ad_manager.create_ad(
        &maker_addr,
        &SorobanString::from_str(&env, &tp.ad_id),
        &bytes32_to_bytesn(&env, &tp.ad_chain_token),
        &tp.amount,
        &tp.order_chain_id,
        &bytes32_to_bytesn(&env, &tp.ad_recipient),
        &bytes32_to_bytesn(&env, &tp.ad_settlement_signer),
    );

    TestSetup {
        env,
        tp,
        ad_manager,
        order_portal,
        ad_merkle_addr: ad_merkle_id.clone(),
        order_merkle_addr: order_merkle_id.clone(),
        admin_addr,
        maker_addr,
        key_registry,
        ad_token_addr,
        order_token_addr,
    }
}

